package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.sql.SQLException;
import java.util.*;

/** Once-per-record triggers dispatch into the existing durable job engine. */
final class EventWorkflows {
 private EventWorkflows() {}
 static void assignee(Store.Db db,Object value)throws SQLException {
  require(value instanceof String,"Assignee must be a username or empty text");String name=(String)value;if(name.isEmpty())return;WorkJobs.text(name,80);var user=db.one("SELECT * FROM os_user WHERE name=? AND active=1 AND role IN ('admin','agent')",name);require(user!=null && !PasswordReset.required(user),"Choose currently eligible staff");
 }
 static Map<String,Object> definition(Store.Db db,Object input)throws SQLException {
  var body=object(input);require(body.keySet().equals(Set.of("name","table","event","state","actions")),"Provide name, table, event, state and actions");String name=WorkJobs.text(body.get("name"),160),table=WorkJobs.text(body.get("table"),80),event=WorkJobs.text(body.get("event"),30),state=WorkJobs.text(body.get("state"),80);var schema=Service.schema(db,table);RecordPolicy.require(schema,"read",db.viewerRole);RecordPolicy.require(schema,"update",db.viewerRole);require(Set.of("created","entered","created_or_entered").contains(event),"Choose created, entered or created_or_entered");require(object(schema.get("states")).containsKey(state),"Choose a current record state");require(body.get("actions") instanceof List<?> list && !list.isEmpty() && list.size()<=3,"Choose one to three native actions");var actions=new ArrayList<Map<String,Object>>();var seen=new HashSet<String>();
  for(Object value:(List<?>)body.get("actions")){var action=object(value);String kind=WorkJobs.text(action.get("kind"),20);require(Set.of("assign","task","note","subflow").contains(kind) && seen.add(kind),"Use each supported action at most once");var normalized=map("kind",kind);if(kind.equals("subflow")){normalized=RecordSubflows.validate(db,table,action);}else if(kind.equals("assign")){require(action.keySet().equals(Set.of("kind","group_id","assignee")),"Provide assignment group and assignee");require(object(schema.get("fields")).keySet().containsAll(Set.of("assignment_group","assigned_to")),"This record type does not support assignment");String group=WorkJobs.text(action.get("group_id"),32);Service.readRecord(db,"sys_user_group",group);assignee(db,action.get("assignee"));normalized.putAll(map("group_id",group,"assignee",action.get("assignee")));}else if(kind.equals("task")){require(action.keySet().equals(Set.of("kind","group_id","summary","details","required","close_at")) && action.get("required") instanceof Boolean,"Provide team, summary, details, required flag and completion state");String group=WorkJobs.text(action.get("group_id"),32),close=WorkJobs.text(action.get("close_at"),80);Service.readRecord(db,"sys_user_group",group);require(object(schema.get("states")).containsKey(close),"Choose a current completion state");normalized.putAll(map("group_id",group,"summary",WorkJobs.text(action.get("summary"),160),"details",WorkJobs.text(action.get("details"),4000),"required",action.get("required"),"close_at",close));}else{require(action.keySet().equals(Set.of("kind","text")),"Provide internal note text");normalized.put("text",WorkJobs.text(action.get("text"),4000));}actions.add(normalized);}
  return map("name",name,"table",table,"event",event,"state",state,"actions",actions);
 }
 static Map<String,Object> page(Store.Db db,String id,Map<String,String> args)throws SQLException {
  Service.requireAccountAdministrator(db,db.viewerId);require(Set.of("table").containsAll(args.keySet()),"Choose only a record type");var flow=id.isEmpty()?null:db.one("SELECT * FROM os_event_flow WHERE flow_id=?",id);if(!id.isEmpty() && flow==null)throw new Failure(404,"Event flow not found");String table=flow==null?args.getOrDefault("table","incident"):flow.get("table_name").toString();var schema=Service.schema(db,table);RecordPolicy.require(schema,"read",db.viewerRole);var definitions=db.all("SELECT * FROM os_event_flow ORDER BY name,flow_id");for(var row:definitions)row.put("owner_available",ConditionalClocks.owner(db,row)!=null);var tables=new ArrayList<Map<String,Object>>();for(var row:db.all("SELECT name,definition FROM os_schema ORDER BY name"))if(!object(object(row.get("definition")).get("states")).isEmpty())tables.add(map("name",row.get("name"),"label",object(row.get("definition")).get("label")));var definition=flow==null?map("name","","table",table,"event","created_or_entered","state","","actions",List.of()):object(flow.get("definition"));var selected=map("assign",map("group_id","","assignee",""),"task",map("group_id","","summary","","details","","required",false,"close_at",""),"note",map("text",""));var enabled=new HashSet<String>();for(var action:objects(definition.get("actions"))){selected.put(action.get("kind").toString(),action);enabled.add(action.get("kind").toString());}var groups=RecordPolicy.allows(Service.schema(db,"sys_user_group"),"read",db.viewerRole)?Service.page(db,"sys_user_group",Map.of("sysparm_limit","100"),"").rows():List.of();return map("flows",definitions,"flow",flow==null?map("flow_id","","revision",0,"active",1):flow,"definition",definition,"states",schema.get("states"),"tables",tables,"groups",groups,"selected",selected,"enabled",enabled,"used",!id.isEmpty() && db.count("SELECT COUNT(*) FROM os_event_run WHERE flow_id=?",id)>0);
 }
 static Map<String,Object> form(Map<String,String> input){
  var form=new LinkedHashMap<>(input);form.remove("csrf");if(form.keySet().equals(Set.of("revision","active"))){require(Set.of("true","false").contains(form.get("active")),"Choose flow availability");return map("revision",Service.number(form.get("revision"),0,Integer.MAX_VALUE),"active",Boolean.valueOf(form.get("active")));}require(form.keySet().equals(Set.of("revision","active","name","table","event","state","assign_enabled","assign_group","assignee","task_enabled","task_group","task_summary","task_details","task_required","close_at","note_enabled","note")),"Provide the current flow form fields");for(String field:List.of("active","assign_enabled","task_enabled","task_required","note_enabled"))require(Set.of("true","false").contains(form.get(field)),"Choose supported Boolean options");var actions=new ArrayList<Map<String,Object>>();if(form.get("assign_enabled").equals("true"))actions.add(map("kind","assign","group_id",form.get("assign_group"),"assignee",form.get("assignee")));if(form.get("task_enabled").equals("true"))actions.add(map("kind","task","group_id",form.get("task_group"),"summary",form.get("task_summary"),"details",form.get("task_details"),"required",Boolean.valueOf(form.get("task_required")),"close_at",form.get("close_at")));if(form.get("note_enabled").equals("true"))actions.add(map("kind","note","text",form.get("note")));return map("revision",Service.number(form.get("revision"),0,Integer.MAX_VALUE),"active",Boolean.valueOf(form.get("active")),"definition",map("name",form.get("name"),"table",form.get("table"),"event",form.get("event"),"state",form.get("state"),"actions",actions));
 }
 static Map<String,Object> save(Store.Db db,String id,Object input)throws SQLException {
  if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");Service.requireAccountAdministrator(db,db.viewerId);var body=object(input);require((body.keySet().equals(Set.of("revision","active","definition")) || body.keySet().equals(Set.of("revision","active"))) && body.get("active") instanceof Boolean,"Provide revision, Boolean active and definition");var before=id.isEmpty()?null:db.one("SELECT * FROM os_event_flow WHERE flow_id=?",id);if(!id.isEmpty() && before==null)throw new Failure(404,"Event flow not found");ProblemInvestigations.revision(body.get("revision"),before==null?0:before.get("revision"));require(before!=null || body.containsKey("definition"),"A new flow requires its definition");var definition=body.containsKey("definition")?definition(db,body.get("definition")):object(before.get("definition"));if(before!=null && db.count("SELECT COUNT(*) FROM os_event_run WHERE flow_id=?",id)>0 && !object(before.get("definition")).equals(definition))throw new Failure(409,"A triggered flow keeps its meaning; create a replacement");int revision=before==null?1:((Number)before.get("revision")).intValue()+1,active=Boolean.TRUE.equals(body.get("active"))?1:0;if(before==null){require(db.count("SELECT COUNT(*) FROM os_event_flow")<100,"At most100 retained event flows are supported");id=Values.id();db.update("INSERT INTO os_event_flow(flow_id,name,table_name,definition,active,revision,owner_id) VALUES(?,?,?,?,?,?,?)",id,definition.get("name"),definition.get("table"),JSON.writeValueAsString(definition),active,revision,db.viewerId);}else db.update("UPDATE os_event_flow SET name=?,table_name=?,definition=?,active=?,revision=? WHERE flow_id=?",definition.get("name"),definition.get("table"),JSON.writeValueAsString(definition),active,revision,id);SecurityEvents.record(db,db.viewerId,db.viewerId,"workflow.saved",map("flow_id",id,"revision",revision,"active",active));return page(db,id,Map.of());
 }
 static void changed(Store.Db db,Map<String,Object> item,Map<String,Object> before,boolean created,long now)throws SQLException {
  if(db.workflowExecution)return;boolean portal=db.employeePortal;try{db.employeePortal=false;for(var flow:db.all("SELECT * FROM os_event_flow WHERE table_name=? AND active=1 ORDER BY flow_id",item.get("table"))){var definition=object(flow.get("definition"));String state=Objects.toString(object(item.get("data")).get("state"),"");if(!state.equals(definition.get("state")))continue;String event=definition.get("event").toString();if(created?event.equals("entered"):event.equals("created") || state.equals(before.get("state")))continue;var owner=ConditionalClocks.owner(db,flow);if(owner==null || !RecordPolicy.allows(Service.schema(db,item.get("table").toString()),"update","admin") || !SlaAlerts.visible(db,owner,item))continue;if(db.count("SELECT COUNT(*) FROM os_event_run WHERE flow_id=? AND record_id=?",flow.get("flow_id"),item.get("sys_id"))>0)continue;require(db.count("SELECT COUNT(*) FROM os_event_run")<5000,"Event workflow retention is full; an administrator must review capacity");db.update("INSERT INTO os_event_run(run_id,flow_id,record_id,record_revision,flow_revision,owner_id,auth_revision,triggered_by,created_at,job_id,state,detail) VALUES(?,?,?,?,?,?,?,?,?,'','pending','{}')",id(),flow.get("flow_id"),item.get("sys_id"),item.get("revision"),flow.get("revision"),owner.get("user_id"),owner.get("auth_revision"),Objects.toString(db.viewerId,""),now);}}finally{db.employeePortal=portal;}
 }
 static Map<String,Object> guard(Store.Db db,Map<String,Object> run)throws SQLException {
  if(!run.get("owner_id").equals(db.viewerId))throw new Failure(403,"Flow execution belongs to its configured owner");var owner=db.one("SELECT * FROM os_user WHERE user_id=? AND active=1 AND role='admin'",db.viewerId);if(owner==null || PasswordReset.required(owner) || ((Number)owner.get("auth_revision")).longValue()!=((Number)run.get("auth_revision")).longValue())throw new Failure(403,"Flow owner authority changed");var flow=db.one("SELECT * FROM os_event_flow WHERE flow_id=?",run.get("flow_id"));if(((Number)flow.get("active")).intValue()!=1 || ((Number)flow.get("revision")).intValue()!=((Number)run.get("flow_revision")).intValue())throw new Failure(409,"Flow is disabled or changed");var record=Service.record(db,flow.get("table_name").toString(),run.get("record_id").toString());RecordPolicy.require(Service.schema(db,flow.get("table_name").toString()),"update",db.viewerRole);ProblemInvestigations.revision(run.get("record_revision"),record.get("revision"));return map("flow",flow,"record",record);
 }
 static Map<String,Object> validate(Store.Db db,String actor,String key,Object input)throws SQLException {
  var body=object(input);require(body.keySet().equals(Set.of("run_id")),"Provide only the retained run identity");String id=WorkJobs.text(body.get("run_id"),32);require(key.equals("flow-"+id),"Use this run's durable job key");var run=db.one("SELECT * FROM os_event_run WHERE run_id=?",id);if(run==null)throw new Failure(404,"Workflow run not found");if(!run.get("owner_id").equals(actor))throw new Failure(403,"Only the configured owner may dispatch this run");if(!run.get("state").equals("pending"))throw new Failure(409,"This run is no longer pending");guard(db,run);return run;
 }
 static void queued(Store.Db db,String job,Object input)throws SQLException {var body=object(input);db.update("UPDATE os_event_run SET state='queued',job_id=? WHERE run_id=?",job,body.get("run_id"));}
 static void dispatch(Store store)throws Exception {
  try(var db=store.open()){if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var run=db.one("SELECT * FROM os_event_run WHERE state='pending' ORDER BY created_at,run_id LIMIT 1");if(run!=null && db.count("SELECT COUNT(*) FROM os_work")<5000){db.viewerId=run.get("owner_id").toString();db.viewerRole="admin";var point=db.connection.setSavepoint();try{WorkJobs.enqueue(store,db,db.viewerId,map("kind","workflow.run","key","flow-"+run.get("run_id"),"payload",map("run_id",run.get("run_id"))));}catch(Failure invalid){db.connection.rollback(point);db.update("UPDATE os_event_run SET state='cancelled',detail=? WHERE run_id=?",JSON.writeValueAsString(map("error","AUTHORITY_OR_INPUT_UNAVAILABLE")),run.get("run_id"));}db.connection.commit();}}
 }
 static Map<String,Object> execute(Store.Db db,Map<String,Object> job,Object input)throws Exception {
  var body=object(input);require(body.keySet().equals(Set.of("run_id")),"Provide only the retained run identity");var run=db.one("SELECT * FROM os_event_run WHERE run_id=? AND job_id=?",WorkJobs.text(body.get("run_id"),32),job.get("job_id"));if(run==null)throw new Failure(404,"Workflow run not found for this job");if(!run.get("state").equals("queued"))throw new Failure(409,"Workflow run is not queued");var context=guard(db,run);var flow=object(context.get("flow"));String table=flow.get("table_name").toString(),record=run.get("record_id").toString(),actor=Service.account(db,db.viewerId).get("name").toString();var receipts=new ArrayList<Map<String,Object>>();boolean previous=db.workflowExecution;try{db.workflowExecution=true;int ordinal=0;for(var action:objects(object(flow.get("definition")).get("actions"))){var current=Service.record(db,table,record);String kind=action.get("kind").toString(),task="";if(kind.equals("subflow")){RecordSubflows.start(db,current,action,run.get("run_id").toString());}else if(kind.equals("assign")){Service.readRecord(db,"sys_user_group",action.get("group_id").toString());assignee(db,action.get("assignee"));Service.update(db,table,current,map("assignment_group",action.get("group_id"),"assigned_to",action.get("assignee")),actor,db.viewerRole,current.get("revision").toString());}else if(kind.equals("task")){var plan=WorkTasks.plan(db,record);if(((Number)plan.get("revision")).intValue()==0){WorkTasks.command(db,table,record,map("operation","configure","revision",0,"record_revision",current.get("revision"),"close_at",action.get("close_at")));plan=WorkTasks.plan(db,record);current=Service.record(db,table,record);}require(plan.get("close_at").equals(action.get("close_at")),"Existing completion gate differs from the workflow plan");var result=WorkTasks.command(db,table,record,map("operation","create","revision",plan.get("revision"),"record_revision",current.get("revision"),"summary",action.get("summary"),"details",action.get("details"),"group_id",action.get("group_id"),"required",action.get("required"),"predecessors",List.of()));task=objects(result.get("tasks")).getLast().get("task_id").toString();}else{Service.audit(db,current,actor,"note",map("body",action.get("text")));}receipts.add(map("step",++ordinal,"kind",kind,"task_id",task,"record_revision",Service.readRecord(db,table,record).get("revision")));}var result=map("run_id",run.get("run_id"),"record_id",record,"steps",receipts);db.update("UPDATE os_event_run SET detail=? WHERE run_id=?",JSON.writeValueAsString(result),run.get("run_id"));return result;}finally{db.workflowExecution=previous;}
 }
 static void finished(Store.Db db,String job,String state,String error)throws SQLException {if(state.equals("succeeded"))db.update("UPDATE os_event_run SET state=? WHERE job_id=?",state,job);else db.update("UPDATE os_event_run SET state=?,detail=? WHERE job_id=?",state,JSON.writeValueAsString(map("error",error)),job);}
 static Map<String,Object> history(Store.Db db,String table,String record)throws SQLException {
  if(!Set.of("admin","agent").contains(db.viewerRole))throw new Failure(403,"Staff workflow access required");var item=Service.readRecord(db,table,record);var rows=db.all("SELECT r.run_id,r.flow_revision,r.record_revision,r.created_at,r.job_id,r.state,r.detail,f.name FROM os_event_run r JOIN os_event_flow f ON f.flow_id=r.flow_id WHERE r.record_id=? ORDER BY r.created_at DESC,r.run_id",record);for(var row:rows){row.put("created",ServiceOutages.stamp(((Number)row.get("created_at")).longValue()));row.put("job_available",db.count("SELECT COUNT(*) FROM os_work WHERE job_id=?",row.get("job_id"))>0);}return map("record",FieldAccess.serialize(db,item),"runs",rows);
 }
}
